CREATE TABLE `users` (
  `id_user` int(10) NOT NULL AUTO_INCREMENT,
  `jabatan` int(10) NOT NULL,
  `nama` text NOT NULL,
  `kelamin` int(10) NOT NULL,
  `agama` int(10) NOT NULL,
  `nip` text NOT NULL,
  `nuptk` text NOT NULL,
  `kontak` text NOT NULL,
  `id_kepegawaian` int(10) NOT NULL,
  `ijazah` int(10) NOT NULL,
  `id_tugas_tambahan` int(10) NOT NULL,
  `username` text NOT NULL,
  `pass` text NOT NULL,
  `password` varchar(250) NOT NULL,
  `foto` text NOT NULL,
  `moto` text NOT NULL,
  PRIMARY KEY (`id_user`),
  KEY `kelamin` (`kelamin`),
  KEY `agama` (`agama`),
  KEY `id_tugas_tambahan` (`id_tugas_tambahan`),
  KEY `id_kepegawaian` (`id_kepegawaian`)
) ENGINE=InnoDB AUTO_INCREMENT=41 DEFAULT CHARSET=latin1;

