INSERT INTO `sub_elemen` VALUES("1","1","1","01.01.01","Mengenal dan Mencintai Tuhan Yang Maha Esa","Menerapkan pemahamannya tentang kualitas atau sifat-sifat Tuhan dalam ritual ibadahnya baik ibadah yang bersifat personal maupun sosial.");
INSERT INTO `sub_elemen` VALUES("2","1","1","01.01.02","Pemahaman Agama/Kepercayaan","Memahami struktur organisasi, unsurunsur utama agama / kepercayaan dalam konteks Indonesia, memahami kontribusi agama/kepercayaan terhadap peradaban dunia.");
INSERT INTO `sub_elemen` VALUES("3","1","1","01.01.03","Pelaksanaan Ritual Ibadah","");
INSERT INTO `sub_elemen` VALUES("4","1","2","01.02.01","Integritas","");
INSERT INTO `sub_elemen` VALUES("5","1","2","01.02.02","Merawat Diri secara Fisik, Mental dan Spiritual","");
INSERT INTO `sub_elemen` VALUES("6","1","3","01.03.01","Mengutamakan persamaan dengan orang lain dan menghargai perbedaan","");
INSERT INTO `sub_elemen` VALUES("7","1","3","01.03.02","Berempati kepada orang lain","");
INSERT INTO `sub_elemen` VALUES("8","1","4","01.04.01","Memahami Keterhubungan Ekosistem Bumi","");
INSERT INTO `sub_elemen` VALUES("9","1","4","01.04.02","Menjaga Lingkungan Alam Sekitar","");
INSERT INTO `sub_elemen` VALUES("10","1","5","01.05.01","Melaksanakan Hak dan Kewajiban sebagai Warga Negara Indonesia","");
INSERT INTO `sub_elemen` VALUES("11","2","6","02.06.01","Mendalami budaya dan identitas budaya","");
INSERT INTO `sub_elemen` VALUES("12","2","6","02.06.02","Mengeksplorasi dan membandingkan pengetahuan budaya, kepercayaan, serta praktiknya","Menganalisis dinamika budaya yang mencakup pemahaman, kepercayaan, dan praktik keseharian dalam rentang waktu yang panjang dan konteks yang luas.");
INSERT INTO `sub_elemen` VALUES("13","2","6","02.06.03","Menumbuhkan rasa menghormati terhadap keanekaragaman budaya","");
INSERT INTO `sub_elemen` VALUES("14","2","7","02.07.01","Berkomunikasi antar budaya","");
INSERT INTO `sub_elemen` VALUES("15","2","7","02.07.02","Mempertimbangkan dan menumbuhkan berbagai perspektif","Menyajikan pandangan yang seimbang mengenai permasalahan yang dapat menimbulkan pertentangan pendapat. Memosisikan orang lain dan budaya yang berbeda darinya secara setara, serta bersedia memberikan pertolongan ketika orang lain berada dalam situasi sulit");
INSERT INTO `sub_elemen` VALUES("16","2","8","02.08.01","Refleksi terhadap pengalaman kebinekaan","");
INSERT INTO `sub_elemen` VALUES("17","2","8","02.08.02","Menghilangkan stereotip dan prasangka","");
INSERT INTO `sub_elemen` VALUES("18","2","8","02.08.03","Menyelaraskan perbedaan budaya","");
INSERT INTO `sub_elemen` VALUES("19","2","9","02.09.01","Aktif membangun masyarakat yang inklusif, adil, dan berkelanjutan","");
INSERT INTO `sub_elemen` VALUES("20","2","9","02.09.02","Berpartisipasi dalam proses pengambilan keputusan bersama","");
INSERT INTO `sub_elemen` VALUES("21","2","9","02.09.03","Memahami peran individu dalam demokrasi","");
INSERT INTO `sub_elemen` VALUES("22","3","10","03.10.01","Kerja sama","Membangun tim dan mengelola kerjasama untuk mencapai tujuan bersama sesuai dengan target yang sudah ditentukan.");
INSERT INTO `sub_elemen` VALUES("23","3","10","03.10.02","Komunikasi untuk mencapai tujuan bersama","");
INSERT INTO `sub_elemen` VALUES("24","3","10","03.10.03","Saling-ketergantungan positif","Menyelaraskan kapasitas kelompok agar para anggota kelompok dapat saling membantu satu sama lain memenuhi kebutuhan mereka baik secara individual maupun kolektif.");
INSERT INTO `sub_elemen` VALUES("25","3","10","03.10.04","Koordinasi Sosial","Menyelaraskan dan menjaga tindakan diri dan anggota kelompok agar sesuai antara satu dengan lainnya serta menerima konsekuensi tindakannya dalam rangka mencapai tujuan bersama");
INSERT INTO `sub_elemen` VALUES("26","3","11","03.11.01","Tanggap terhadap lingkungan Sosial","Tanggap terhadap lingkungan sosial sesuai dengan tuntutan peran sosialnya dan berkontribusi sesuai dengan kebutuhan masyarakat untuk menghasilkan keadaan yang lebih baik.");
INSERT INTO `sub_elemen` VALUES("27","3","11","03.11.02","Persepsi sosial","Melakukan tindakan yang tepat agar orang lain merespon sesuai dengan yang diharapkan dalam rangka penyelesaian pekerjaan dan pencapaian tujuan");
INSERT INTO `sub_elemen` VALUES("28","3","12","03.12.01","Berbagi","Mengupayakan memberi hal yang dianggap penting dan berharga kepada orang-orang yang membutuhkan di masyarakat yang lebih luas (negara, dunia).");
INSERT INTO `sub_elemen` VALUES("29","4","13","04.13.01","Mengenali kualitas dan minat diri serta tantangan yang dihadapi","Mengidentifikasi kekuatan dan tantangan-tantangan yang akan dihadapi pada konteks pembelajaran, sosial dan pekerjaan yang akan dipilihnya di masa depan.");
INSERT INTO `sub_elemen` VALUES("30","4","13","04.13.02","Mengembangkan refleksi diri","Melakukan refleksi terhadap umpan balik dari teman, guru, dan orang dewasa lainnya, serta informasiinformasi karir yang akan dipilihnya untuk menganalisis karakteristik dan keterampilan yang dibutuhkan dalam menunjang atau menghambat karirnya di masa depan.");
INSERT INTO `sub_elemen` VALUES("31","4","14","04.14.01","Regulasi emosi","Mengendalikan dan menyesuaikan emosi yang dirasakannya secara tepat ketika menghadapi situasi yang menantang dan menekan pada konteks belajar, relasi, dan pekerjaan.");
INSERT INTO `sub_elemen` VALUES("32","4","14","04.14.02","Penetapan tujuan belajar, prestasi, dan pengembangan diri serta rencana strategis untuk mencapainya","Mengevaluasi efektivitas strategi pembelajaran digunakannya, serta menetapkan tujuan belajar, prestasi, dan pengembangan diri secara spesifik dan merancang strategi yang sesuai untuk menghadapi tantangan-tantangan yang akan dihadapi pada konteks pembelajaran, sosial dan pekerjaan yang akan dipilihnya di masa depan.");
INSERT INTO `sub_elemen` VALUES("33","4","14","04.14.03","Menunjukkan inisiatif dan bekerja secara mandiri","Menentukan prioritas pribadi, berinisiatif mencari dan mengembangkan pengetahuan dan keterampilan yang spesifik sesuai tujuan di masa depan.");
INSERT INTO `sub_elemen` VALUES("34","4","14","04.14.04","Mengembangkan pengendalian dan disiplin diri","Melakukan tindakantindakan secara konsisten guna mencapai tujuan karir dan pengembangan dirinya di masa depan, serta berusaha mencari dan melakukan alternatif tindakan lain yang dapat dilakukan ketika menemui hambatan.");
INSERT INTO `sub_elemen` VALUES("35","4","14","04.14.05","Percaya diri, tangguh (resilient), dan adaptif","Menyesuaikan dan mulai menjalankan rencana dan strategi pengembangan dirinya dengan mempertimbangkan minat dan tuntutan pada konteks belajar maupun pekerjaan yang akan dijalaninya di masa depan, serta berusaha untuk mengatasi tantangantantangan yang ditemui.");
INSERT INTO `sub_elemen` VALUES("36","5","15","05.15.01","Mengajukan pertanyaan","Mengajukan pertanyaan untuk menganalisis secara kritis permasalahan yang kompleks dan abstrak.");
INSERT INTO `sub_elemen` VALUES("37","5","15","05.15.02","Mengidentifikasi, mengklarifikasi, dan mengolah informasi dan gagasan","Secara kritis mengklarifikasi serta menganalisis gagasan dan informasi yang kompleks dan abstrak dari berbagai sumber. Memprioritaskan suatu gagasan yang paling relevan dari hasil klarifikasi dan analisis.");
INSERT INTO `sub_elemen` VALUES("38","5","16","05.16.01","Menganalisis dan mengevaluasi penalaran dan prosedurnya","Menganalisis dan mengevaluasi penalaran yang digunakannya dalam menemukan dan mencari solusi serta mengambil keputusan.");
INSERT INTO `sub_elemen` VALUES("39","5","17","05.17.01","Merefleksi dan mengevaluasi pemikirannya sendiri","Menjelaskan alasan untuk mendukung pemikirannya dan memikirkan pandangan yang mungkin berlawanan dengan pemikirannya dan mengubah pemikirannya jika diperlukan.");
INSERT INTO `sub_elemen` VALUES("40","6","18","06.18.01","Menghasilkan gagasan yang orisinal","Menghasilkan gagasan yang beragam untuk mengekspresikan pikiran dan/atau perasaannya, menilai gagasannya, serta memikirkan segala risikonya dengan mempertimbangkan banyak perspektif seperti etika dan nilai kemanusiaan ketika gagasannya direalisasikan.");
INSERT INTO `sub_elemen` VALUES("41","6","19","06.19.01","Menghasilkan karya dan tindakan yang orisinal","Mengeksplorasi dan mengekspresikan pikiran dan/atau perasaannya dalam bentuk karya dan/ atau tindakan, serta mengevaluasinya dan mempertimbangkan dampak dan risikonya bagi diri dan lingkungannya dengan menggunakan berbagai perspektif.");
INSERT INTO `sub_elemen` VALUES("42","6","20","06.20.01","Memiliki keluwesan berpikir dalam mencari alternatif solusi permasalahan","Bereksperimen dengan berbagai pilihan secara kreatif untuk memodifikasi gagasan sesuai dengan perubahan situasi.");
